mapper.select:
select id, member_id as memberId, poi_key as poiKey, poi_name as poiName, lat, lng
from member_visited_poi
where member_id = #{memberId}
  and lat between #{minLat} and #{maxLat}
  and lng between #{minLng} and #{maxLng}

select id, name as poiName, lat, lng
from roam_poi
where type = 1 and status = 1
  and lat between #{minLat} and #{maxLat}
  and lng between #{minLng} and #{maxLng}
